package com.kisanmitra.review;
import com.kisanmitra.user.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/reviews") @RequiredArgsConstructor public class ReviewController {private final ReviewRepository reviews; private final UserRepository users;
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object>b,Authentication a){User reviewer=user(a);User target=users.findById(UUID.fromString((String)b.get("targetUser"))).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));int rating=((Number)b.getOrDefault("rating",5)).intValue();if(rating<1||rating>5)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);Review r=new Review();r.setReviewer(reviewer);r.setTargetUser(target);r.setRating(rating);r.setComment((String)b.getOrDefault("comment",""));return ResponseEntity.status(201).body(Map.of("success",true,"data",reviews.save(r)));}
 @GetMapping("/user/{id}") public Map<String,Object> userReviews(@PathVariable UUID id){return Map.of("success",true,"data",reviews.findByTargetUserIdOrderByCreatedAtDesc(id));}
 @PostMapping("/{id}/respond") public Map<String,Object> respond(@PathVariable UUID id,@RequestBody Map<String,String>b,Authentication a){Review r=reviews.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!r.getTargetUser().getId().equals(user(a).getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);r.setResponse(b.getOrDefault("response",""));return Map.of("success",true,"data",reviews.save(r));}
 private User user(Authentication a){if(a==null||!(a.getPrincipal() instanceof User u))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return u;}}
